<?php elseif($tab==='plan'):?><section class="card p-3 mb-3"><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap"><div><h5 class="mb-0">Tạo và tối ưu</h5><small class="text-muted">Chỉ chạy khi bấm nút, tối đa khoảng 8 giây.</small></div><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="generate"><input type="hidden" name="return_tab" value="plan"><?php if($activePlan):?><label class="align-self-center"><input type="checkbox" name="keep_locked" value="1" checked> Giữ tiết khóa</label><?php endif;?><button class="btn btn-primary"><i class="bi bi-cpu"></i> <?=$activePlan?'Tối ưu lại':'Tạo phương án'?></button></form></div></section><?php if($activePlan):?><div class="kpis mb-3"><div class="kpi"><strong><?=count($activePlan['entries'])?></strong>Đã xếp</div><div class="kpi"><strong><?=count($activePlan['unplaced'])?></strong>Chưa xếp</div><div class="kpi"><strong><?=count($activePlan['errors'])?></strong>Xung đột</div><div class="kpi"><strong><?=count(array_filter($activePlan['entries'],fn($e)=>!empty($e['locked'])))?></strong>Đã khóa</div><div class="kpi"><strong><?=number_format((int)$activePlan['score'])?></strong>Điểm phạt</div></div><?php if($activePlan['unplaced']):?><div class="alert alert-warning"><?=e(implode('; ',array_map(fn($a)=>$a['subject'].' '.$a['teacher'].' ('.implode('+',$a['classes']).')',$activePlan['unplaced'])))?></div><?php endif;?><section class="card overflow-hidden"><div class="table-responsive"><table class="table table-sm plan-table mb-0"><thead><tr><th>Thứ</th><th>Buổi/tiết</th><th>Môn</th><th>Lớp</th><th>Giáo viên</th><th>Chỉnh</th></tr></thead><tbody><?php $sorted=$activePlan['entries'];usort($sorted,fn($a,$b)=>[$a['day'],$a['session'],$a['period']]<=>[$b['day'],$b['session'],$b['period']]);foreach($sorted as$e):?><tr class="<?=count($e['classes'])>1?'table-success':''?>"><td>T<?=e($e['day'])?></td><td><?=e($e['session'])?> · <strong><?=e($e['period'])?></strong></td><td><?=e($e['subject'])?></td><td><?=e(implode(' + ',$e['classes']))?></td><td><?=e($e['teacher'])?></td><td><div class="d-flex gap-1"><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="lock"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><input type="hidden" name="activity_id" value="<?=e($e['activity_id'])?>"><button class="btn btn-sm <?=$e['locked']?'btn-warning':'btn-outline-secondary'?>"><i class="bi bi-lock"></i></button></form><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="move"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><input type="hidden" name="activity_id" value="<?=e($e['activity_id'])?>"><select class="form-select form-select-sm" name="day"><?php foreach($data['settings']['days']as$d):?><option value="<?=$d?>" <?=$d==$e['day']?'selected':''?>>T<?=$d?></option><?php endforeach;?></select><select class="form-select form-select-sm" name="session"><option <?=$e['session']==='Sáng'?'selected':''?>>Sáng</option><option <?=$e['session']==='Chiều'?'selected':''?>>Chiều</option></select><input class="form-control form-control-sm" style="width:60px" type="number" name="period" value="<?=e($e['period'])?>"><button class="btn btn-sm btn-outline-primary">Đổi</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><form method="post" class="mt-2" onsubmit="return confirm('Xóa bản nháp?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete_plan"><input type="hidden" name="id" value="<?=e($activePlan['id'])?>"><button class="btn btn-outline-danger btn-sm">Xóa bản nháp</button></form><?php else:?><div class="alert alert-info">Chưa có phương án.</div><?php endif;?>
<?php elseif($tab==='publish'):?><section class="card p-4"><h4>Duyệt và công bố</h4><p class="text-muted">Tạo phiên bản mới; TKB cũ vẫn ở Lịch sử để khôi phục.</p><?php if(!$activePlan):?><div class="alert alert-warning">Chưa có phương án.</div><?php else:$valid=empty($activePlan['unplaced'])&&empty($activePlan['errors']);?><div class="alert <?=$valid?'alert-success':'alert-danger'?>"><?=$valid?'Phương án hợp lệ.':'Còn tiết chưa xếp hoặc xung đột.'?></div><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="return_tab" value="publish"><input type="hidden" name="plan_id" value="<?=e($activePlan['id'])?>"><div class="col-md-4"><input class="form-control" name="name" value="TKB tự động <?=date('d-m-Y')?>"></div><div class="col-md-4"><input class="form-control" type="date" name="week_from" required></div><div class="col-md-4"><input class="form-control" type="date" name="week_to" required></div><div><button class="btn btn-success" <?=$valid?'':'disabled'?>>Công bố sang TKB chính</button></div></form><?php endif;?></section>
<?php else:?><section class="card p-4"><h4>Bật hoặc tắt ứng dụng</h4><p>Tắt ứng dụng không xóa PCCM, Sổ đầu bài hoặc TKB đã công bố.</p><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="toggle"><label class="form-check form-switch fs-5"><input class="form-check-input" type="checkbox" name="enabled" value="1" <?=$data['enabled']?'checked':''?>> Cho phép xếp TKB</label><button class="btn btn-primary mt-3">Lưu</button></form></section><?php endif;?></main></body></html>
